foreach($marker in $expertMarkers){if($marker.Value -ne 'BATCH_MARK moe_expert_order tokens=8192 buckets=256 permutation_only=1 scratch_bytes=16780292 host_count_reads=0 original_candidates=1 original_k16=1 original_stream=1'){throw 'Expert-order identity mismatch'}}
