if($checkpointLines.Count -ne 3 -or @($checkpointLines|Where-Object {$_ -notmatch ' complete=1 '}).Count -ne 0){throw 'Complete model checkpoints were not captured'}
if($r.summary.checkpoint_owner_tokens -ne $ownerTokens -or $r.summary.checkpoint_owner_first_token -ne 82 -or -not $r.summary.checkpoint_owner_logit_valid -or [Math]::Abs($r.summary.checkpoint_owner_first_logit-9.25) -gt 0.125){throw 'Owner GB10 token/logit boundary failed'}
